type Props={view:string;work:any;units:any[];members:any[];member:any;tenant:string;busy:boolean;post:(body:any,path?:string)=>Promise<boolean>;health?:any};
function Frame({view,children,title}:any){const page=crmSubpageByView[view];return <section className="panel crm-independent-page" aria-label={view}><div className="crm-independent-head"><div><p className="eyebrow">CRM · INDEPENDENT PAGE</p><h1>{title||page?.label||view}</h1><p className="fine">{page?.description||'授权范围内的独立业务页面。'}</p></div><span className="crm-page-badge">独立数据视图</span></div>{['公司与部门','持牌机构'].includes(view)&&<OrganizationModelNotice mode="units"/>}{view==='员工与角色'&&<OrganizationModelNotice mode="members"/>}{children}</section>}
const columnLabels:Record<string,string>={id:'编号',status:'状态',customerId:'客户',amount:'本金',fee:'费用',dueAt:'到期时间',loanId:'贷款编号',kind:'类型',cents:'金额（分）',createdAt:'时间',type:'事件类型',action:'操作',at:'时间',note:'备注',email:'邮箱',role:'岗位',active:'状态',name:'名称'};
const eventLabels:Record<string,string>={institution_auto_paused:'机构自动暂停',platform_update_company:'更新公司',create_company:'创建公司',client_language_config:'语言配置',kyc_field_permission:'KYC 字段权限',notification_template_save:'保存通知模板',assignment_mode:'分配模式',add_unit:'新增组织',update_unit:'更新组织',funding_risk_acknowledged:'确认资金风险',funding_risk_resolved:'关闭资金风险',service_routing_save:'保存承接路由',service_auto_assign:'自动分配承接机构',emergency_access_requested:'申请应急授权',risk_rule_create:'创建风控规则',risk_rule_update:'更新风控规则',risk_rule_submit_review:'提交风控审核',risk_rule_review:'审核风控规则',risk_rule_pause:'暂停风控规则',legacy_loan_quarantined:'隔离历史贷款',legacy_loan_backfill:'回填历史贷款',report_export:'导出报表',funding_settings_save:'保存资金配置',audit_manifest_created:'创建审计快照'};
const callbackLabels:Record<string,string>={loan_approved:'贷款审批结果',loan_disbursed:'放款结果',repayment_posted:'还款入账',loan_closed:'贷款结清'};
const callbackStatusLabels:Record<string,string>={queued:'待发送',processing:'发送中',delivered:'已送达',retrying:'重试中',dead_letter:'待人工重试',failed:'发送失败'};
const riskStatusLabels:Record<string,string>={open:'待处理',acknowledged:'已确认',mitigating:'处理中',resolved:'已关闭',recorded:'已记录'};
function displayCellValue(row:any,column:string){const value=row[column];if(column==='status'&&typeof value==='string')return statusNames[value as keyof typeof statusNames]||value;if(column==='active')return value===0||value==='0'?'已停用':'启用';if(column==='kind'&&typeof value==='string')return ({institution:'持牌机构',department:'运营部门',postloan:'贷后部门'} as Record<string,string>)[value]||value;if(column==='role'&&typeof value==='string')return roleLabels[value as TeamRole]||value;if((column==='action'||column==='type')&&typeof value==='string')return actionLabels[value]||eventLabels[value]||value;return value??'—'}
function Rows({rows,columns}:{rows:any[];columns:string[]}){return <div className="table-scroll"><table><thead><tr>{columns.map(c=><th key={c}>{columnLabels[c]||c}</th>)}</tr></thead><tbody>{rows.length?rows.map((row:any,i:number)=><tr key={row.id||row.customerId||i}>{columns.map(c=><td key={c}>{String(displayCellValue(row,c))}</td>)}</tr>):<tr><td colSpan={columns.length}>当前授权范围内暂无数据。</td></tr>}</tbody></table></div>}
function csvCell(value:any){
 const text=String(value??'').replace(/\r?\n/g,' ');
 const safe=/^[=+\-@]/.test(text)?`'${text}`:text;
 return `"${safe.replaceAll('"','""')}"`;
}
function downloadRows(view:string,rows:any[],columns:string[]){const csv='\ufeff'+[columns.map(c=>csvCell(columnLabels[c]||c)).join(','),...rows.map(row=>columns.map(c=>csvCell(row[c])).join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`khmerx-${view}.csv`;link.click();URL.revokeObjectURL(url)}
function SearchableRows({rows,columns,view}:{rows:any[];columns:string[];view?:string}){const [query,setQuery]=useState('');const filtered=useMemo(()=>{const q=query.toLowerCase().trim();return rows.filter(row=>!q||columns.some(column=>String(displayCellValue(row,column)).toLowerCase().includes(q)||String(row[column]??'').toLowerCase().includes(q)))},[rows,columns,query]);return <><div className="crm-filter-row"><label>页面搜索<Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索当前页面数据"/></label>{view&&<Button type="button" variant="outline" onClick={()=>downloadRows(view,filtered,columns)}>导出当前查询 CSV</Button>}</div><p className="fine">当前结果 {filtered.length} / {rows.length} 条，仅包含当前授权范围。</p><Rows rows={filtered} columns={columns}/></>}
function OrganizationModelNotice({mode}:{mode:'units'|'members'}){return <aside className="crm-org-model" aria-label="组织架构边界"><div><strong>{mode==='units'?'组织架构边界':'权限对象边界'}</strong><p>{mode==='units'?'公司是租户根节点；部门负责内部运营分工，持牌机构是独立业务主体，二者不是同一层级。':'角色是系统权限模板，岗位是员工承担的业务职责；员工再绑定一个主部门或持牌机构，数据范围由归属与指派共同决定。'}</p></div><div className="crm-org-flow"><span>公司</span><i>→</i><span>{mode==='units'?'部门／持牌机构':'员工账号'}</span><i>→</i><span>{mode==='units'?'员工与业务':'角色／岗位与数据范围'}</span></div></aside>}
function UnitCreate({busy,post,defaultKind='department',allowInstitution=true}:{busy:boolean;post:any;defaultKind?:'department'|'institution'|'postloan';allowInstitution?:boolean}){const [name,setName]=useState(''),[kind,setKind]=useState<'department'|'institution'|'postloan'>(defaultKind),[code,setCode]=useState(''),[license,setLicense]=useState(''),[expires,setExpires]=useState(''),[callback,setCallback]=useState(''),[currencies,setCurrencies]=useState('USD'),[message,setMessage]=useState('');const institution=kind==='institution';return <section className="crm-action-panel"><h2>{defaultKind==='institution'?'新增持牌机构（业务主体）':'新增部门'}</h2><p className="fine">{institution?'持牌机构用于贷款审批、放款和回调边界，不属于内部部门。':'部门用于公司内部运营分工；员工主归属只能选择一个部门或持牌机构。'}</p><div className="team-grid"><label>{allowInstitution?'类型':'部门类型'}<select value={kind} onChange={e=>setKind(e.target.value as typeof kind)} disabled={defaultKind==='institution'}><option value="department">贷前运营部门</option><option value="postloan">运营贷后部门</option>{allowInstitution&&<option value="institution">持牌机构</option>}</select></label><label>名称<Input value={name} onChange={e=>setName(e.target.value)} placeholder={institution?'例如：UAT测试持牌机构':'例如：运营审核部'}/></label>{institution&&<><label>机构代码<Input value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="例如 UAT-LENDER-01" maxLength={40}/></label><label>牌照编号<Input value={license} onChange={e=>setLicense(e.target.value)} maxLength={80}/></label><label>牌照有效期<Input type="date" value={expires} onChange={e=>setExpires(e.target.value)}/></label><label>支持币种<Input value={currencies} onChange={e=>setCurrencies(e.target.value.toUpperCase())} placeholder="USD,KHR"/></label><label>回调地址<Input value={callback} onChange={e=>setCallback(e.target.value)} placeholder="https://..."/></label></>}</div><Button disabled={busy||!name.trim()||(institution&&(!code.trim()||!license.trim()||!expires||!currencies.trim()))} onClick={async()=>{const body:any={action:'add_unit',name:name.trim(),kind};if(institution)Object.assign(body,{institutionCode:code,licenseNumber:license,licenseExpiresAt:expires,callbackUrl:callback,supportedCurrencies:currencies.split(',').map(x=>x.trim()).filter(Boolean)});if(await post(body)){setName('');setCode('');setLicense('');setExpires('');setCallback('');setMessage('已新增并写入审计记录')}}}>新增</Button>{message&&<p className="success" role="status">{message}</p>}</section>}
function UnitManagement({units,busy,post,mode=units.length&&units.every((u:any)=>u.kind==='institution')?'institutions':'departments'}:{units:any[];busy:boolean;post:any;mode?:'departments'|'institutions'|'units'}){const [query,setQuery]=useState(''),[status,setStatus]=useState('all');const q=query.trim().toLowerCase();const filtered=units.filter((u:any)=>{const kind=u.kind==='institution'?'持牌机构':u.kind==='postloan'?'贷后部门':'运营部门';return (!q||`${u.name} ${kind}`.toLowerCase().includes(q))&&(status==='all'||(status==='active'?u.active!==0:u.active===0))});const label=mode==='institutions'?'持牌机构':mode==='departments'?'部门':'组织';return <section className="crm-action-panel"><h2>{label}目录</h2><p className="fine">{mode==='institutions'?'仅维护持牌业务主体、牌照和回调配置；机构审批与放款权限由员工岗位单独控制。':'仅维护公司内部部门与运营分工；部门不承载牌照、审批或放款主体属性。'}停用前需先迁移员工、业务分配和承接路由。</p><div className="crm-filter-row"><label>搜索{label}<Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="名称或类型"/></label><label>状态<select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">全部</option><option value="active">启用</option><option value="inactive">已停用</option></select></label><span className="fine">显示 {filtered.length} / {units.length} 个{label}</span></div><div className="table-scroll"><table><thead><tr><th>名称</th><th>类型</th><th>状态</th><th>变更原因与操作</th></tr></thead><tbody>{filtered.length?filtered.map((u:any)=><UnitManagementRow key={u.id+':'+u.active} unit={u} busy={busy} post={post}/>):<tr><td colSpan={4}><div className="empty"><strong>暂无匹配{label}</strong><span>请调整名称或状态筛选条件。</span></div></td></tr>}</tbody></table></div></section>}
function UnitManagementRow({unit,busy,post}:{unit:any;busy:boolean;post:any}){const [name,setName]=useState(unit.name),[active,setActive]=useState(unit.active!==0),[institutionCode,setInstitutionCode]=useState(unit.institution_code||''),[licenseNumber,setLicenseNumber]=useState(unit.license_number||''),[licenseExpiresAt,setLicenseExpiresAt]=useState(unit.license_expires_at||''),[callbackUrl,setCallbackUrl]=useState(unit.callback_url||''),[supportedCurrencies,setSupportedCurrencies]=useState<string>(()=>{try{return JSON.parse(unit.supported_currencies_json||'["USD"]').join(',')}catch{return 'USD'}}),[reason,setReason]=useState('');const kind=unit.kind==='institution'?'持牌机构':unit.kind==='postloan'?'贷后部门':'运营部门';const institution=unit.kind==='institution',deactivating=unit.active!==0&&!active;return <tr><td><Input aria-label={unit.name+' 名称'} value={name} maxLength={120} onChange={e=>setName(e.target.value)}/>{institution&&<div className="team-grid"><Input aria-label={unit.name+' 机构代码'} placeholder="机构代码" value={institutionCode} maxLength={40} onChange={e=>setInstitutionCode(e.target.value.toUpperCase())}/><Input aria-label={unit.name+' 牌照编号'} placeholder="牌照编号" value={licenseNumber} maxLength={80} onChange={e=>setLicenseNumber(e.target.value)}/><Input aria-label={unit.name+' 牌照有效期'} type="date" value={licenseExpiresAt} onChange={e=>setLicenseExpiresAt(e.target.value)}/><Input aria-label={unit.name+' 回调地址'} placeholder="https://..." value={callbackUrl} maxLength={500} onChange={e=>setCallbackUrl(e.target.value)}/><Input aria-label={unit.name+' 支持币种'} placeholder="USD,KHR" value={supportedCurrencies} maxLength={40} onChange={e=>setSupportedCurrencies(e.target.value.toUpperCase())}/></div>}</td><td>{kind}</td><td><select aria-label={unit.name+' 状态'} value={active?'1':'0'} onChange={e=>setActive(e.target.value==='1')}><option value="1">启用</option><option value="0">已停用</option></select>{deactivating&&<small className="fine">停用前必须迁移员工、业务分配和默认路由</small>}</td><td><Input aria-label={unit.name+' 变更原因'} placeholder={deactivating?'停用原因（需先完成迁移）':'变更原因'} value={reason} maxLength={300} onChange={e=>setReason(e.target.value)}/><Button variant="outline" disabled={busy||!name.trim()||!reason.trim()} onClick={()=>void post({action:'update_unit',unitId:unit.id,name,active,reason,...(institution?{institutionCode,licenseNumber,licenseExpiresAt,callbackUrl,supportedCurrencies:supportedCurrencies.split(',').map(x=>x.trim()).filter(Boolean)}:{})})}>{deactivating?'提交停用申请':'保存'}</Button></td></tr>}
function MemberManagement({members,units,busy,post}:{members:any[];units:any[];busy:boolean;post:any}){const [query,setQuery]=useState(''),[role,setRole]=useState(''),[unitId,setUnitId]=useState(''),[active,setActive]=useState(''),[page,setPage]=useState(1),[result,setResult]=useState<any>(null),[error,setError]=useState('');const pageSize=20;useEffect(()=>{let cancelled=false;const timer=window.setTimeout(()=>{const params=new URLSearchParams({page:String(page),pageSize:String(pageSize),query,role,unitId,active});void apiFetch<any>(`/api/team/members?${params}`,{cache:'no-store'}).then(({data})=>{if(!cancelled){if(data.pages&&page>data.pages){setPage(data.pages);return}setResult(data);setError('')}}).catch(e=>{if(!cancelled){setResult(null);setError((e as Error).message)}})},180);return()=>{cancelled=true;window.clearTimeout(timer)}},[page,query,role,unitId,active,members]);const rows=result?.items||(!query&&!role&&!unitId&&!active&&page===1?members:[]),total=result?.total??members.length,pages=result?.pages||Math.max(1,Math.ceil(total/pageSize));const reset=(setter:any)=>(e:any)=>{setter(e.target.value);setPage(1)};return <><div className="crm-filter-row"><label>搜索员工<Input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="邮箱、岗位或部门／机构"/></label><label>岗位<select value={role} onChange={reset(setRole)}><option value="">全部岗位</option>{Object.entries(roleLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>状态<select value={active} onChange={reset(setActive)}><option value="">全部状态</option><option value="1">启用</option><option value="0">已停用</option></select></label><span className="fine">显示 {rows.length} / {total} 名员工</span></div><div className="crm-filter-row"><label>部门／机构<select value={unitId} onChange={reset(setUnitId)}><option value="">全部部门／机构</option>{units.map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label></div>{error&&<p className="error" role="alert">{error}</p>}<div className="table-scroll"><table><thead><tr><th>员工</th><th>岗位</th><th>部门／机构</th><th>状态</th><th>MFA</th><th>最后登录</th><th>操作</th></tr></thead><tbody>{rows.length?rows.map((m:any)=><MemberManagementRow key={m.id+':'+m.version} m={m} units={units} busy={busy} post={post}/>):<tr><td colSpan={7}><div className="empty"><strong>暂无匹配员工</strong><span>请调整筛选条件，或先新增员工。</span></div></td></tr>}</tbody></table></div><div className="crm-filter-row"><span className="fine">第 {page} / {pages} 页</span><div className="button-row"><Button variant="outline" disabled={page<=1} onClick={()=>setPage(p=>p-1)}>上一页</Button><Button variant="outline" disabled={page>=pages} onClick={()=>setPage(p=>p+1)}>下一页</Button></div></div></>}
function RolePermissionMatrix(){const actions=Object.keys(actionRoles);return <section className="crm-action-panel"><h2>岗位权限矩阵</h2><p className="fine">权限由系统策略固定管理；岗位仅能在所属公司和部门／持牌机构范围内执行对应动作。</p><div className="table-scroll"><table><thead><tr><th>岗位</th><th>职责与范围</th><th>高风险</th><th>可执行动作</th></tr></thead><tbody>{Object.entries(roleLabels).map(([key,label])=>{const role=key as TeamRole;const granted=actions.filter(action=>actionRoles[action].includes(role)).map(actionLabelsFor);const display=[...granted,...(roleDisplayActions[role]||[])];return <tr key={role}><td><strong>{label}</strong></td><td>{roleCatalog[role].description}</td><td>{roleCatalog[role].highRisk?'需双人授权':'常规'}</td><td>{display.length?display.join('、'):'查看与协作'}</td></tr>})}</tbody></table></div></section>}
function FieldPermissionsPage({members}:{members:any[]}){const groups=Object.entries(kycFieldGroups);return <section className="crm-action-panel"><h2>KYC 字段授权</h2><p className="fine">此页仅展示当前公司授权范围内的生效配置；字段授权请在“员工与角色”中修改，修改原因会写入权限变更审计。</p><div className="table-scroll"><table><thead><tr><th>员工</th><th>岗位</th><th>数据范围</th><th>已授权字段组</th></tr></thead><tbody>{members.length?members.map((m:any)=><tr key={m.id}><td>{m.email}</td><td>{roleLabels[m.role as TeamRole]||m.role}</td><td>{m.data_scope==='assigned'?'仅指派案件':m.data_scope==='department'?'所属部门':m.data_scope==='institution'?'所属持牌机构':'当前公司'}</td><td>{(m.kycFieldPermissions||[]).length?(m.kycFieldPermissions||[]).map((group:string)=>kycFieldGroups[group as keyof typeof kycFieldGroups]||group).join('、'):'未授权字段修改'}</td></tr>):<tr><td colSpan={4}>当前岗位无可查看的员工字段授权记录。</td></tr>}</tbody></table></div><p className="fine">可授权字段组：{groups.map(([key,label])=>`${label}（${key}）`).join('、')}。</p></section>}
function DataScopePage({members}:{members:any[]}){return <section className="crm-action-panel"><h2>数据范围矩阵</h2><p className="fine">数据范围由岗位策略自动计算，并叠加公司、部门／持牌机构和业务指派关系；此页只读展示，变更岗位或归属请在“员工与角色”完成并保留审计。</p><div className="table-scroll"><table><thead><tr><th>员工</th><th>岗位</th><th>默认范围</th><th>生效说明</th><th>状态</th></tr></thead><tbody>{members.length?members.map((m:any)=>{const scope=dataScopeForRole(m.role as TeamRole);const explanation=scope==='company'?'当前公司全部业务与审计记录':scope==='department'?'所属部门内的业务和分配任务':scope==='institution'?'所属持牌机构贷款与放款任务':scope==='assigned'?'仅本人被指派的 KYC 案件':'按岗位策略与业务指派关系';return <tr key={m.id}><td>{m.email}</td><td>{roleLabels[m.role as TeamRole]||m.role}</td><td>{dataScopeLabels[scope]}</td><td>{explanation}</td><td>{m.active?'启用':'已停用'}</td></tr>}) : <tr><td colSpan={5}>当前公司暂无可展示的员工数据范围。</td></tr>}</tbody></table></div><p className="fine">系统在每次接口请求同时校验公司、员工状态、岗位、部门／机构、业务指派和数据版本号。</p></section>}
function LocaleSettingsPage(){const {locale,setLocale}=useAdminLocale();const [busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');async function choose(next:any){setBusy(true);setMessage('');setError('');try{await apiFetch('/api/team/locale',{method:'POST',body:JSON.stringify({locale:next})});setLocale(next);setMessage('语言设置已保存并记录审计')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <section className="crm-action-panel"><h2>语言与时区</h2><p className="fine">语言偏好按当前员工账号保存；客户端可用语言仍由公司管理员在公司设置中统一控制。时区用于资金限额、账务日期和审计时间展示。</p>{error&&<p className="error" role="alert">{error}</p>}{message&&<p className="success" role="status">{message}</p>}<fieldset className="language-config"><legend>后台语言</legend><label><input type="radio" name="team-locale" checked={locale==='zh'} disabled={busy} onChange={()=>void choose('zh')}/>🇨🇳 中文</label><label><input type="radio" name="team-locale" checked={locale==='en'} disabled={busy} onChange={()=>void choose('en')}/>🇬🇧 English</label><label><input type="radio" name="team-locale" checked={locale==='km'} disabled={busy} onChange={()=>void choose('km')}/>🇰🇭 Khmer</label></fieldset><div className="sample"><strong>当前业务时区</strong><p>Asia/Phnom_Penh（柬埔寨）</p><span className="fine">时区由平台统一管理，避免跨公司账务日期不一致。</span></div></section>}
function ApiApplicationsPage({units,member}:{units:any[];member:any}){const [events,setEvents]=useState<any[]|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function load(){try{const {data}=await apiFetch<any>('/api/team/institution-callbacks',{cache:'no-store'});setEvents(data.events||[]);setError('')}catch(e){setError((e as Error).message);setEvents([])}}useEffect(()=>{void load()},[]);async function retry(id:string){setBusy(true);try{await apiFetch('/api/team/institution-callbacks',{method:'POST',body:JSON.stringify({action:'retry',eventId:id})});await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}const rows=events||[];return <section className="crm-action-panel"><h2>API 应用与机构回调</h2><p className="fine">仅展示当前公司机构回调的脱敏运行状态，不返回回调密钥、签名原文或完整载荷。应用凭证由平台安全配置管理，轮换后旧密钥立即失效。</p>{error&&<p className="error" role="alert">{error}</p>}<div className="crm-page-kpis"><div><strong>{rows.length}</strong><span>回调事件</span></div><div><strong>{rows.filter((x:any)=>x.status==='dead_letter').length}</strong><span>待人工重试</span></div><div><strong>HTTPS</strong><span>回调传输要求</span></div></div>{rows.length?<div className="table-scroll"><table><thead><tr><th>机构</th><th>事件类型</th><th>状态</th><th>最近尝试</th><th>更新时间</th><th>操作</th></tr></thead><tbody>{rows.map((row:any)=><tr key={row.id}><td>{units.find((u:any)=>u.id===row.institution_id)?.name||row.institution_id}</td><td>{callbackLabels[row.event_type]||row.event_type||'—'}</td><td>{callbackStatusLabels[row.status]||row.status||'—'}</td><td>{callbackStatusLabels[row.attempt_status]||row.attempt_status||'—'} · {row.attempt??'—'}</td><td>{row.updated_at||row.created_at||'—'}</td><td>{row.status==='dead_letter'&&member?.role==='admin'?<Button variant="outline" disabled={busy} onClick={()=>void retry(row.id)}>人工重试</Button>:<span className="fine">只读</span>}</td></tr>)}</tbody></table></div>:<div className="empty"><strong>暂无机构回调事件</strong><span>机构完成 HTTPS 回调接入后，运行状态会显示在这里。</span></div>}<div className="sample"><strong>安全边界</strong><p>每个事件必须带签名、幂等键、事件编号和请求追踪号；重复事件不会重复入库，死信只能由公司 Admin 按审计记录人工重试。</p></div></section>}
function FileScanConfigPage(){return <section className="crm-action-panel"><h2>文件与扫描配置</h2><p className="fine">统一展示 KYC 材料上传门禁；扫描凭证和底层存储地址不在后台回显。</p><div className="crm-page-kpis"><div><strong>10 MB</strong><span>单文件上限</span></div><div><strong>40</strong><span>活动材料上限</span></div><div><strong>SHA-256</strong><span>完整性校验</span></div></div><div className="team-audit-list"><article className="team-audit"><div className="team-audit-head"><strong>安全扫描</strong><span>上传前强制执行</span></div><p>服务端先完成大小限制、病毒扫描和 SHA-256 校验，再写入私有加密存储；扫描失败不会留下可用材料记录。</p></article><article className="team-audit"><div className="team-audit-head"><strong>重拍与替换</strong><span>保留历史审计</span></div><p>同一资料位替换时仅当前版本计入活动上限，旧版本保留用于审核追溯，不向客户或普通员工暴露。</p></article><article className="team-audit"><div className="team-audit-head"><strong>配置边界</strong><span>只读</span></div><p>扫描服务地址、访问令牌、加密密钥和存储桶均由部署环境管理；本页不提供前端编辑入口，避免敏感配置泄露。</p></article></div></section>}
function SystemHealthPage({state}:{state:any}){const checks=[['后台认证',state?.member?'正常':'待验证',!!state?.member],['公司数据隔离',state?.company?'已生效':'待验证',!!state?.company],['员工状态校验',state?.member?.active===0?'已停用':'已启用',state?.member?.active!==0],['审计链路',Array.isArray(state?.trail)?'可读取':'按角色限制',Array.isArray(state?.trail)]];return <section className="crm-action-panel"><h2>系统健康</h2><p className="fine">按当前登录员工和公司范围读取运行检查，不暴露基础设施密钥、数据库连接或跨公司数据。</p><div className="team-audit-list">{checks.map(([name,status,ok])=><article className="team-audit" key={String(name)}><div className="team-audit-head"><strong>{name}</strong><span className={ok?'success':''}>{status}</span></div><p>{name==='后台认证'?'员工会话、公司选择和岗位权限由服务端同时校验。':name==='公司数据隔离'?'请求仅返回当前公司可见组织、业务和审计数据。':name==='员工状态校验'?'停用员工无法继续访问受保护页面和接口。':'管理员和审计岗位可查看审计轨迹，其他岗位按最小权限返回。'}</p></article>)}</div><p className="fine">最后检查：{new Date().toLocaleString('zh-CN',{timeZone:'Asia/Phnom_Penh'})}（Asia/Phnom_Penh）</p></section>}
function AuditSecurityPage({view,state}:{view:string;state:any}){const trail=Array.isArray(state?.trail)?state.trail:[],match=view==='权限变更'?/member|permission|role|mfa|session|unit/i:view==='资金操作'?/fund|repay|disburse|payment|loan/i:view==='数据修改'?/update|amend|edit|save/i:view==='安全告警'?/alert|risk|freeze|failed|denied/i:null,rows=match?trail.filter((x:any)=>match.test(`${x.action||''} ${x.detail||''}`)):trail;return <section className="crm-action-panel"><h2>{view}</h2><p className="fine">仅展示当前公司范围内的脱敏审计摘要；敏感字段、令牌、完整请求载荷和跨公司记录不会在此回显。</p><div className="crm-page-kpis"><div><strong>{rows.length}</strong><span>可见记录</span></div><div><strong>{state?.member?.mfa_enabled?'已启用':'未启用'}</strong><span>当前员工 MFA</span></div><div><strong>{state?.company?.name||'当前公司'}</strong><span>数据范围</span></div></div>{rows.length?<div className="team-audit-list">{rows.slice(0,100).map((item:any,i:number)=><article className="team-audit" key={`${item.created_at||''}:${i}`}><div className="team-audit-head"><strong>{actionLabels[item.action]||eventLabels[item.action]||item.action||'业务操作'}</strong><span>{item.created_at||'—'}</span></div><p>操作人：{item.actor||'—'} · 详细内容按最小权限脱敏展示。</p></article>)}</div>:<div className="empty"><strong>暂无可见审计记录</strong><span>当前筛选范围没有匹配记录，或当前岗位仅可查看汇总状态。</span></div>}<p className="fine">审计记录由服务端写入，查询本身不修改业务状态。</p></section>}
function LoginSecurityPage({state}:{state:any}){const rows=(Array.isArray(state?.trail)?state.trail:[]).filter((x:any)=>/login|logout|mfa|session|recovery/i.test(String(x.action||''))).slice(0,50);return <section className="crm-action-panel"><h2>登录与 IP</h2><p className="fine">查看当前公司登录安全状态。IP 地址、登录设备和恢复凭证仅按审计权限脱敏展示，不在前端保存或回显认证秘密。</p><div className="crm-page-kpis"><div><strong>{state?.member?.mfa_enabled?'已启用':'未启用'}</strong><span>当前员工 MFA</span></div><div><strong>{rows.length}</strong><span>登录安全记录</span></div><div><strong>服务端</strong><span>会话校验位置</span></div></div><div className="team-audit-list"><article className="team-audit"><div className="team-audit-head"><strong>MFA 与会话</strong><span>{state?.member?.mfa_enabled?'正常':'建议启用'}</span></div><p>员工状态、公司选择、岗位权限和 MFA 会话由服务端同时校验；停用员工会立即失去受保护接口访问权限。</p></article><article className="team-audit"><div className="team-audit-head"><strong>IP 与设备记录</strong><span>脱敏</span></div><p>登录、退出、失败尝试和恢复码生成均写入当前公司审计。未授权岗位不会看到完整 IP、设备指纹或恢复码。</p></article></div>{rows.length?<div className="team-audit-list">{rows.map((item:any,i:number)=><article className="team-audit" key={`${item.created_at||''}:${i}`}><div className="team-audit-head"><strong>{item.action||'登录安全事件'}</strong><span>{item.created_at||'—'}</span></div><p>操作人：{item.actor||'—'} · 网络与设备信息按权限脱敏。</p></article>)}</div>:<div className="empty"><strong>暂无登录安全记录</strong><span>当前公司还没有可展示的登录、退出或 MFA 操作记录。</span></div>}<p className="fine">本页只读，任何安全配置变更必须回到员工与角色页面完成并写入审计。</p></section>}
function AuditExportPage({role}:{role?:string}){return <section className="crm-action-panel"><h2>审计导出</h2><p className="fine">导出前先生成当前公司审计完整性快照；导出内容按当前岗位数据范围脱敏，并把导出动作写入审计记录。</p><div className="crm-page-kpis"><div><strong>当前公司</strong><span>导出范围</span></div><div><strong>脱敏</strong><span>敏感字段策略</span></div><div><strong>SHA-256</strong><span>完整性校验</span></div></div><AuditIntegrity role={role}/><p className="fine">平台不会在导出文件中包含密码、MFA 秘密、回调密钥、完整证件号或原始文件内容。</p></section>}
function actionLabelsFor(action:string){return actionLabels[action]||action}
function MemberCreate({units,busy,post}:{units:any[];busy:boolean;post:any}){const [email,setEmail]=useState(''),[role,setRole]=useState<TeamRole>('ops'),[unit,setUnit]=useState(''),[emergencyId,setEmergencyId]=useState(''),[passwordLogin,setPasswordLogin]=useState(false),[message,setMessage]=useState('');const unitKind=roleUnitKind(role);const needsUnit=!!unitKind,highRisk=roleCatalog[role].highRisk;return <section className="crm-action-panel"><h2>新增员工</h2><div className="team-grid"><label>登录邮箱<Input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="staff@example.com"/></label><label>岗位<select value={role} onChange={e=>{setRole(e.target.value as TeamRole);setUnit('');setEmergencyId('')}}>{Object.entries(roleLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><span className="fine">{roleCatalog[role].description}{highRisk?'；需另一名 Admin 二次授权':''}</span></label>{needsUnit&&<label>所属部门／机构<select value={unit} onChange={e=>setUnit(e.target.value)}><option value="">请选择</option>{units.filter((u:any)=>u.active!==0&&u.kind===unitKind).map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label>}{highRisk&&<label>二次授权 ID<Input value={emergencyId} onChange={e=>setEmergencyId(e.target.value)} placeholder="由另一名 Admin 批准后填写"/><span className="fine">批准范围需包含员工权限，且申请人不能批准自己。</span></label>}</div><label className="check"><input type="checkbox" checked={passwordLogin} onChange={e=>setPasswordLogin(e.target.checked)}/>测试环境生成独立密码（生产环境将被拒绝）</label><Button disabled={busy||!/^\S+@\S+\.\S+$/.test(email)||(needsUnit&&!unit)||(highRisk&&!emergencyId.trim())} onClick={async()=>{if(await post({action:'create_member',email,role,unitId:unit,passwordLogin,...(highRisk?{emergencyId:emergencyId.trim()}:{})})){setEmail('');setUnit('');setEmergencyId('');setMessage('员工已创建；如返回一次性登录信息，请立即保存')}}}>新增员工</Button>{message&&<p className="success" role="status">{message}</p>}</section>}
function MemberManagementRow({m,units,busy,post}:{m:any;units:any[];busy:boolean;post:any}){const [role,setRole]=useState<TeamRole>(m.role),[unit,setUnit]=useState(m.unit_id||''),[active,setActive]=useState(!!m.active),[emergencyId,setEmergencyId]=useState(''),[reason,setReason]=useState('');const unitKind=roleUnitKind(role);const needsUnit=!!unitKind,highRisk=roleCatalog[role].highRisk,needsApproval=highRisk&&(role!==m.role||(unit||null)!==(m.unit_id||null));return <tr><td>{m.email}</td><td><select aria-label={`${m.email} 岗位`} value={role} onChange={e=>{setRole(e.target.value as TeamRole);setUnit('');setEmergencyId('')}}>{Object.entries(roleLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><span className="fine">{roleCatalog[role].description}{highRisk?'；改派需另一名 Admin 二次授权':''}</span>{needsApproval&&<Input aria-label={`${m.email} 二次授权 ID`} value={emergencyId} onChange={e=>setEmergencyId(e.target.value)} placeholder="二次授权 ID"/>}</td><td>{needsUnit?<select aria-label={`${m.email} 部门／机构`} value={unit} onChange={e=>setUnit(e.target.value)}><option value="">请选择</option>{units.filter((u:any)=>u.active!==0&&u.kind===unitKind).map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select>:'公司全部范围'}</td><td><select aria-label={`${m.email} 状态`} value={active?'1':'0'} onChange={e=>setActive(e.target.value==='1')}><option value="1">启用</option><option value="0">已停用</option></select></td><td>{m.mfa_enabled?'已启用':'未启用'}</td><td>{m.last_login_at?new Date(m.last_login_at).toLocaleString('zh-CN',{timeZone:'Asia/Phnom_Penh'}):'从未登录'}</td><td><Input aria-label={`${m.email} 变更原因`} value={reason} maxLength={300} onChange={e=>setReason(e.target.value)} placeholder="变更原因"/><div className="button-row"><Button variant="outline" disabled={busy||!reason.trim()||(needsUnit&&!unit)||(needsApproval&&!emergencyId.trim())} onClick={()=>void post({action:'update_member',memberId:m.id,role,unitId:unit,active,version:m.version,reason,...(needsApproval?{emergencyId:emergencyId.trim()}:{})})}>保存修改</Button>{m.active&&<><Button variant="outline" disabled={busy||!reason.trim()} onClick={()=>void post({action:'reset_member_password',memberId:m.id,reason})}>重置密码</Button><Button variant="outline" disabled={busy||!reason.trim()} onClick={()=>void post({action:'revoke_member_sessions',memberId:m.id,reason})}>撤销会话</Button></>}</div>{['kyc','dept_admin'].includes(role)&&<details><summary>KYC 字段修改权限（已启用 {(m.kycFieldPermissions||[]).length} 项）</summary><p className="fine">只允许修改已授权字段；修改后必须由客户重新提交审核。</p>{Object.entries(kycFieldGroups).map(([group,label])=><label key={group}><input type="checkbox" checked={(m.kycFieldPermissions||[]).includes(group)} disabled={busy} onChange={e=>void post({action:'kyc_field_permission',memberId:m.id,fieldGroup:group,enabled:e.target.checked,reason:reason||'调整 KYC 字段授权'})}/>{label}</label>)}</details>}</td></tr>}
function PricingIndependent({pricing,busy,post}:{pricing?:Pricing;busy:boolean;post:any}){const initial=pricing||defaultPricing,[p,setP]=useState(initial);let preview:any,error='';try{preview=calculateBill(10000,p,'preview')}catch(e){error=(e as Error).message}return <section className="crm-action-panel"><h2>费率与费用</h2><p className="fine">仅影响新建申请；已签约或已生成账单的费用快照不变。当前版本 {initial.version}。</p><div className="team-grid"><label>服务费（放款扣除，%）<Input type="number" min="0" max="100" step="0.01" value={p.serviceBps/100} onChange={e=>setP({...p,serviceBps:Math.round(Number(e.target.value)*100)})}/></label><label>年利率（%）<Input type="number" min="0" max="100" step="0.01" value={p.annualInterestBps/100} onChange={e=>setP({...p,annualInterestBps:Math.round(Number(e.target.value)*100)})}/></label><label>利息收取<select value={p.interestTiming} onChange={e=>setP({...p,interestTiming:e.target.value as Pricing['interestTiming']})}><option value="upfront">放款时扣除</option><option value="repayment">还款时收取</option></select></label></div>{error&&<p className="error">{error}</p>}{preview&&<LoanBill bill={preview}/>}<Button disabled={busy||!!error} onClick={()=>void post({action:'pricing_save',...p})}>保存费用配置</Button></section>}
function FundingSettings(){const [data,setData]=useState<any>(undefined),[daily,setDaily]=useState('10000'),[monthly,setMonthly]=useState('30000'),[warning,setWarning]=useState('20'),[message,setMessage]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function load(){try{const {data:d}=await apiFetch<any>('/api/team/funding-settings',{cache:'no-store'});setData(d);setDaily(String((d.settings.dailyCents/100).toFixed(2)));setMonthly(String((d.settings.monthlyCents/100).toFixed(2)));setWarning(String(d.settings.warningPercent));setError('')}catch(e){setError((e as Error).message)}}useEffect(()=>{void load()},[]);async function save(){setBusy(true);setMessage('');try{const {data:d}=await apiFetch<any>('/api/team/funding-settings',{method:'POST',body:JSON.stringify({dailyCents:Math.round(Number(daily)*100),monthlyCents:Math.round(Number(monthly)*100),warningPercent:Number(warning),version:data.settings.version})});setData({...data,settings:d.settings});setMessage('资金配置已保存并记录审计')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}const invalid=Number(daily)<=0||Number(monthly)<Number(daily)||Number(warning)<=0||Number(warning)>=100;return <section className="crm-action-panel funding-settings-panel"><div className="funding-settings-head"><div><p className="eyebrow">FUNDING LIMITS</p><h2>资金限额配置</h2><p className="fine">按公司保存每日、每月放款上限和预警比例，修改后新放款立即使用新版本。</p></div><span className="crm-page-badge">公司级配置</span></div>{error&&<p className="error" role="alert">{error}</p>}{data===undefined?<div className="funding-settings-actions"><Button onClick={()=>void load()}>读取资金配置</Button></div>:data.editable?<><div className="funding-settings-grid"><article className="funding-setting-card"><span className="funding-setting-kicker">DAILY LIMIT</span><label>每日放款限额（USD）<Input type="number" min="1" step="0.01" value={daily} onChange={e=>setDaily(e.target.value)}/></label><p className="fine">按公司时区自然日累计成功放款。</p></article><article className="funding-setting-card"><span className="funding-setting-kicker">MONTHLY LIMIT</span><label>每月放款限额（USD）<Input type="number" min="1" step="0.01" value={monthly} onChange={e=>setMonthly(e.target.value)}/></label><p className="fine">按公司时区自然月累计成功放款。</p></article><article className="funding-setting-card funding-setting-card-warning"><span className="funding-setting-kicker">WARNING THRESHOLD</span><label>剩余额度预警比例（%）<Input type="number" min="1" max="99" step="1" value={warning} onChange={e=>setWarning(e.target.value)}/></label><p className="fine">剩余额度达到该比例时触发风控提醒。</p></article></div>{Number(monthly)<Number(daily)&&<p className="error">月度限额不能低于日限额</p>}<div className="funding-settings-actions"><Button disabled={busy||invalid} onClick={()=>void save()}>保存资金配置</Button>{message&&<p className="success" role="status">{message}</p>}</div><div className="funding-settings-meta"><span>当前版本 {data.settings.version}</span><span>时区 {data.settings.timezone}</span><span>保存后写入审计记录</span></div></>:<p className="fine">当前岗位仅可查看资金配置。</p>}</section>}
function ConfigPage({view,work,units,members,member,busy,post}:{view:string;work:any;units:any[];members:any[];member:any;busy:boolean;post:any}){const isOrg=view==='公司与部门'||view==='持牌机构';const scopedUnits=view==='持牌机构'?units.filter((u:any)=>u.kind==='institution'):view==='公司与部门'?units.filter((u:any)=>u.kind!=='institution'):units;const rows=isOrg?scopedUnits:view==='员工与角色'?members:view==='资金流水'||view==='对账异常'?(work?.state?.entries||[]):work?.state?.events||[];const columns=view==='员工与角色'?['email','role','active']:isOrg?['name','kind','active']:view==='资金流水'||view==='对账异常'?['kind','cents','createdAt']:['type','action','at'];return <Frame view={view}>{isOrg&&member?.role==='admin'&&<UnitCreate busy={busy} post={post} defaultKind={view==='持牌机构'?'institution':'department'} allowInstitution={view==='持牌机构'}/>} {view==='公司与部门'&&member?.role==='admin'&&<UnitManagement units={scopedUnits} busy={busy} post={post}/>} {view==='持牌机构'&&member?.role==='admin'&&<UnitManagement units={scopedUnits} busy={busy} post={post}/>} {view==='员工与角色'&&member?.role==='admin'?<><RolePermissionMatrix/><MemberCreate units={units} busy={busy} post={post}/><MemberManagement members={members} units={units} busy={busy} post={post}/></>:!isOrg&&<SearchableRows rows={rows} columns={columns} view={view}/>} {isOrg&&member?.role!=='admin'&&<SearchableRows rows={rows} columns={columns} view={view}/>}<p className="fine">新增、修改和启停受当前岗位与公司数据范围约束并写入审计；普通 CSV 是当前筛选结果快照，服务端报表导出会单独写入审计记录。</p></Frame>}
function LoanPage({view,work}:{view:string;work:any}){const loans=work?.state?.loans||[],customerRefs=new Map((work?.customers||[]).map((c:any)=>[c.customerId,c.customerRef]));const filtered=view==='放款管理'?loans.filter((l:any)=>['signed','active','closed','overdue'].includes(l.status)):view==='账单与还款'?loans.filter((l:any)=>l.billing):loans;const rows=filtered.map((l:any)=>({id:l.publicRef||l.id,status:l.status,customerId:customerRefs.get(l.customerId)||l.customerRef||l.customerId||'—',amount:`$${((l.amount||0)/100).toFixed(2)}`,fee:`$${((l.fee||0)/100).toFixed(2)}`,dueAt:l.dueAt||'—'}));return <Frame view={view}><SearchableRows rows={rows} columns={['id','status','customerId','amount','fee','dueAt']} view={view}/></Frame>}
function LoanWorkflowRow({loan:l,role,busy,post}:{loan:any;role:string;busy:boolean;post:any}){const [reason,setReason]=useState('');const action=(name:string)=>post({action:name,loanId:l.id,note:reason,requestId:clientRequestId()},'/api/state');const signed=Boolean(l.signature)||['signed','active','closed'].includes(l.status);return <article className="team-assignment"><h3>{l.name||l.customerId||'贷款申请'} · {l.publicRef||String(l.id).slice(0,8)}</h3><p className="fine">内部订单 ID：{l.id}</p><p>{statusNames[l.status as keyof typeof statusNames]||l.status} · 本金 ${(Number(l.amount||0)/100).toFixed(2)} · 费用 ${(Number(l.fee||0)/100).toFixed(2)} · {l.note||'—'}</p>{l.billing&&<LoanBill bill={l.billing}/>}<div className="button-row">{role==='lender'&&l.status==='decision_pending'&&!l.approvalActor&&<><Button disabled={busy} onClick={()=>void action('approve')}>初审通过</Button><Input aria-label="拒绝原因" placeholder="拒绝原因" value={reason} onChange={e=>setReason(e.target.value)}/><Button variant="outline" disabled={busy||!reason.trim()} onClick={()=>void action('reject')}>拒绝申请</Button></>}{role==='checker'&&l.status==='decision_pending'&&l.approvalActor&&<Button disabled={busy} onClick={()=>void action('approval_check')}>独立复核通过</Button>}</div><p className="fine">初审：{l.approvalActor?'已完成':'待完成'} · 独立复核：{l.approvalCheckedBy?'已完成':'待完成'} · 签约：{signed?'已签署':'待签署'} · 放款：{l.fundingActor?'已完成':'待处理'}</p></article>}
function LoanWorkflowPanel({view,work,member,busy,post}:{view:string;work:any;member:any;busy:boolean;post:any}){const loans=(work?.state?.loans||[]).filter((l:any)=>!['registered','kyc_pending','needs_info'].includes(l.status));const customerRefs=new Map((work?.customers||[]).map((c:any)=>[c.customerId,c.customerRef]));const rows=loans.map((l:any)=>({id:l.publicRef||l.id,status:l.status,customerId:customerRefs.get(l.customerId)||l.customerRef||l.customerId||'—',amount:`$${((l.amount||0)/100).toFixed(2)}`,fee:`$${((l.fee||0)/100).toFixed(2)}`}));const role=member?.role||'';const actionable=loans.filter((l:any)=>(role==='lender'&&l.status==='decision_pending'&&!l.approvalActor)||(role==='checker'&&l.status==='decision_pending'&&!!l.approvalActor));return <Frame view={view}><SearchableRows rows={rows} columns={['id','status','customerId','amount','fee']} view={view}/>{actionable.length>0&&<section className="crm-action-panel"><h2>待处理操作</h2><p className="fine">仅显示当前岗位可执行且尚未完成的审批动作，其他贷款请在上方列表查看。</p>{actionable.map((l:any)=><LoanWorkflowRow key={l.id+':'+l.status} loan={l} role={role} busy={busy} post={post}/>)}</section>}</Frame>}
function FundingOverview({work}:{work:any}){const entries=work?.state?.entries||[],[settings,setSettings]=useState<any>(null),[settingsError,setSettingsError]=useState('');useEffect(()=>{void apiFetch<any>('/api/team/funding-settings',{cache:'no-store'}).then(({data})=>setSettings(data.settings)).catch(e=>setSettingsError((e as Error).message))},[]);const limits=settings||{dailyCents:1000000,monthlyCents:3000000,warningPercent:20,timezone:'Asia/Phnom_Penh'},status=fundingStatus(entries,new Date(),limits);return <Frame view="资金监管"><div className="crm-page-kpis"><div><strong>${(status.dayCents/100).toFixed(2)}</strong><span>今日已放款 / ${(limits.dailyCents/100).toLocaleString()}</span></div><div><strong>${(status.monthCents/100).toFixed(2)}</strong><span>本月已放款 / ${(limits.monthlyCents/100).toLocaleString()}</span></div><div><strong>{status.warning?'预警':'正常'}</strong><span>当前额度状态</span></div></div>{settingsError&&<p className="fine">资金配置读取失败，当前显示系统默认值。</p>}<div className={`funding-risk-banner ${status.blocked?'is-blocked':status.warning?'is-warning':'is-normal'}`}><strong>{status.blocked?'放款已阻断':status.warning?`剩余额度达到 ${limits.warningPercent}% 预警线`:'资金监管正常'}</strong><span>今日剩余 ${(status.dailyRemainingCents/100).toFixed(2)} · 本月剩余 ${(status.monthlyRemainingCents/100).toFixed(2)} · 时区 {status.timezone}</span></div><div className="funding-control-grid"><article><h3>额度使用</h3><p>今日 {status.dailyPercent}%</p><div className="funding-progress"><span style={{width:`${status.dailyPercent}%`}}/></div><p>本月 {status.monthlyPercent}%</p><div className="funding-progress"><span style={{width:`${status.monthlyPercent}%`}}/></div></article><article><h3>控制规则</h3><p className="fine">仅最终成功入账的测试放款计入额度；失败、取消和重复幂等请求不计入。</p><p className="fine">冻结、限额命中和人工解除必须进入风险事件并保留审计记录。</p><p className="fine">当前配置版本：{settings?.version??'默认'} · 最近更新：{settings?.updatedAt||'系统默认'}</p></article></div><p className="fine">当前为测试资金监管视图，不代表真实银行余额；真实资金接入前需完成机构、支付、对账和合规评审。</p></Frame>}
function FundingLedger({work,view}:{work:any;view:string}){const rows=work?.state?.entries||[];return <Frame view={view}><div className="crm-page-kpis"><strong>{rows.length}</strong><span>不可变资金流水</span></div><SearchableRows rows={rows.map((row:any)=>({...row,amount:`$${(Number(row.cents||0)/100).toFixed(2)}`,createdAt:row.at||row.createdAt||'—'}))} columns={['id','kind','amount','loanId','createdAt']} view={view}/><p className="fine">原始流水不可覆盖或删除；纠错只能通过冲正/补偿分录完成。</p></Frame>}
function FundingReconciliation({work}:{work:any}){const events=work?.state?.events||[],rows=events.filter((event:any)=>/对账|差异|回执|冲正/i.test(`${event.type||''} ${event.action||''} ${event.note||''}`));return <Frame view="对账异常"><div className="crm-page-kpis"><strong>{rows.length}</strong><span>待核对异常</span></div>{rows.length?<SearchableRows rows={rows} columns={['type','action','note','at']} view="对账异常"/>:<div className="empty"><strong>暂无对账异常</strong><span>外部回执和内部账本目前没有待核对差异。</span></div>}<p className="fine">外部状态未知时不得直接标记成功；处理结果必须关联流水号、request ID 和审计记录。</p></Frame>}
function WorkQueuePage({view,work,member}:{view:string;work:any;member:any}){const loans=Array.isArray(work?.state?.loans)?work.state.loans:[],kyc=Array.isArray(work?.kycOrders)?work.kycOrders:[],events=Array.isArray(work?.state?.events)?work.state.events:[],rows=view==='我的待办'?kyc:view==='团队队列'?loans:events;const columns=view==='我的待办'?['id','status','updatedAt']:view==='团队队列'?['id','status','amount','updatedAt']:['type','action','at'];const copy=view==='我的待办'?'当前岗位待处理的 KYC 与补件任务':view==='团队队列'?'团队贷款申请、审批和放款队列':'当前公司 SLA、提醒和风险事件摘要';const role=roleLabels[member?.role as TeamRole]||'当前岗位';return <Frame view={view}><div className="crm-page-kpis"><div><strong>{rows.length}</strong><span>当前可见记录</span></div><div><strong>{role}</strong><span>数据范围</span></div><div><strong>服务端</strong><span>状态来源</span></div></div><p className="fine">{copy}。列表按当前公司、岗位、部门／机构和业务指派关系过滤。</p>{rows.length?<SearchableRows rows={rows} columns={columns} view={view}/>:<div className="empty"><strong>暂无待处理记录</strong><span>当前范围内没有需要处理的事项，系统会在状态变化后自动刷新。</span></div>}</Frame>}
function FundingFreeze({work,units,role,memberId}:{work:any;units:any[];role:string;memberId?:string}){const status=fundingStatus(work?.state?.entries||[]);return <Frame view="冻结与解除"><div className={`funding-risk-banner ${status.blocked?'is-blocked':status.warning?'is-warning':'is-normal'}`}><strong>{status.blocked?'当前已达到额度，放款阻断':status.warning?'当前处于额度预警':'当前未触发资金冻结'}</strong><span>解除前必须完成余额核对、对账和双人复核。</span></div>{role==='admin'?<EmergencyAccess units={units} memberId={memberId}/>:<div className="empty"><strong>当前岗位仅可查看冻结状态</strong><span>应急授权申请、批准和撤销仅限公司 Admin，并要求二次 MFA。</span></div>}<p className="fine">应急权限仅允许在明确事件范围内执行受控动作，不会修改历史流水或绕过贷款审批。</p></Frame>}
function RiskEvents({work,role}:{work:any;role:string}){const [items,setItems]=useState<any[]|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[reason,setReason]=useState('');const canResolve=role==='admin';useEffect(()=>{void load()},[]);async function load(){try{const {data}=await apiFetch<any>('/api/team/funding-risk',{cache:'no-store'});setItems(data.items||[]);setError('')}catch(e){setError((e as Error).message);setItems([])}}async function transition(id:string,action:string){setBusy(true);try{await apiFetch('/api/team/funding-risk',{method:'POST',body:JSON.stringify({id,action,reason})});setReason('');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}const fallback=(work?.state?.events||[]).filter((event:any)=>/风险|冻结|限额|预警|对账|冲正|异常/i.test(`${event.type||''} ${event.action||''} ${event.note||''}`));const rows=items===null?fallback:items;return <Frame view="风控事件"><div className="crm-page-kpis"><strong>{rows.length}</strong><span>风险事件与处置记录</span></div>{error&&<p className="error" role="alert">{error}</p>}{canResolve&&<label>处理依据<Input value={reason} maxLength={500} onChange={e=>setReason(e.target.value)} placeholder="确认或关闭风险事件时填写原因"/></label>}{rows.length?<div className="team-audit-list">{rows.map((item:any)=><article className="team-audit" key={item.id}><div className="team-audit-head"><strong>{eventLabels[item.event_type]||eventLabels[item.type]||item.event_type||item.type||'风险事件'}</strong><span>{riskStatusLabels[item.status]||item.status||'记录'}</span></div><p>{item.reason||item.note||'—'}</p><small>{item.created_at||item.at||'—'} · 关联 {item.correlation_id||item.requestId||'—'}</small>{canResolve&&item.status&&<div className="button-row">{item.status==='open'&&<Button variant="outline" disabled={busy||reason.trim().length<5} onClick={()=>void transition(item.id,'acknowledge')}>确认风险</Button>}{['open','acknowledged','mitigating'].includes(item.status)&&<Button variant="ghost" disabled={busy||reason.trim().length<5} onClick={()=>void transition(item.id,'resolve')}>关闭事件</Button>}</div>}</article>)}</div>:<div className="empty"><strong>暂无风险事件</strong><span>当前没有需要处置的额度、监管或对账风险。</span></div>}<p className="fine">风险事件必须保留触发快照、处理人、复核人和关闭依据。</p></Frame>}
function RiskPage({view,work,units=[],role,memberId}:{view:string;work:any;units?:any[];role:string;memberId?:string}){if(view==='资金监管')return <FundingOverview work={work}/>;if(view==='资金限额')return <FundingSettings/>;if(view==='冻结与解除')return <FundingFreeze work={work} units={units} role={role} memberId={memberId}/>;if(view==='风控事件')return <RiskEvents work={work} role={role}/>;if(view==='资金流水')return <FundingLedger work={work} view={view}/>;if(view==='对账异常')return <FundingReconciliation work={work}/>;const events=work?.state?.events||[];return <Frame view={view}><div className="crm-page-kpis"><strong>{events.length}</strong><span>风险/业务事件</span></div><SearchableRows rows={events} columns={['type','action','at']} view={view}/></Frame>}
function roleAllowsCrmView(role:string,view:string){if(role==='admin')return true;const audit=['审计导出','审计与安全','操作审计','登录与 IP','数据修改','资金操作','权限变更','安全告警'];if(audit.includes(view))return role==='audit';if(role==='audit')return ['字段权限','数据范围','系统健康','我的待办','团队队列','SLA 与提醒','风险摘要','客户列表','KYC 审核队列','客户漏斗','KYC 与审批','贷款申请','审批协同','放款管理','账单与还款','还款管理','提现与钱包','合同与签约','业务时间线','资金监管','资金限额','资金流水','对账异常','风控事件','放款与还款','逾期与催收报表','资金监管报表','客服与投诉','自定义报表','客服工单','投诉与争议','通知发送记录','贷后任务','逾期与催收'].includes(view);if(['lender','checker'].includes(role))return ['贷款申请','审批协同','合同与签约'].includes(view);if(role==='finance_checker')return ['放款管理','账单与还款','资金监管','资金流水','对账异常','风控事件'].includes(view);if(role==='finance')return ['放款管理','账单与还款','资金监管','资金限额','冻结与解除','资金流水','对账异常','风控事件','风险摘要','客户漏斗','KYC 与审批','放款与还款','逾期与催收报表','资金监管报表','客服与投诉','自定义报表'].includes(view);if(['kyc','dept_admin'].includes(role))return ['我的待办','客户列表','客户标签与分组','KYC 审核队列','客户漏斗','KYC 与审批','通知发送记录','客服工单','投诉与争议'].includes(view);if(role==='ops')return ['我的待办','客户列表','客户标签与分组','KYC 审核队列','客户漏斗','KYC 与审批','通知发送记录','客服工单','投诉与争议','贷款产品','风控规则与版本'].includes(view);if(['collection_admin','collector'].includes(role))return ['我的待办','客户列表','客户标签与分组','客户漏斗','逾期与催收报表','客服与投诉','客服工单','投诉与争议','通知发送记录','贷后任务','逾期与催收'].includes(view);return ['客户列表','客户标签与分组','客户漏斗','KYC 与审批','KYC 审核队列'].includes(view)}
export function CrmSubpageRouter(props:Props){const view=canonicalCrmView(props.view);if(!roleAllowsCrmView(props.member?.role||'',view))return <Frame view={view} title="无权访问"><div className="empty"><strong>当前岗位无权访问此页面</strong><span>请从当前岗位工作台选择可处理的队列。</span></div></Frame>;if(view==='贷款产品')return <Frame view={view}><LoanProducts role={props.member?.role||''}/></Frame>;if(view==='风控规则与版本')return <Frame view={view}><RiskRules role={props.member?.role||''}/></Frame>;if(view==='字段权限')return <Frame view={view}><FieldPermissionsPage members={props.members}/></Frame>;if(view==='数据范围')return <Frame view={view}><DataScopePage members={props.members}/></Frame>;if(view==='语言与时区')return <Frame view={view}><LocaleSettingsPage/></Frame>;if(view==='API 应用')return <Frame view={view}><ApiApplicationsPage units={props.units} member={props.member}/></Frame>;if(view==='文件与扫描配置')return <Frame view={view}><FileScanConfigPage/></Frame>;if(view==='系统健康')return <Frame view={view}><SystemHealthPage state={props.health}/></Frame>;if(view==='登录与 IP')return <Frame view={view}><LoginSecurityPage state={props.health}/></Frame>;if(view==='审计导出')return <Frame view={view}><AuditExportPage role={props.member?.role||''}/></Frame>;if(view==='审计与安全')return <Frame view={view}><AuditSecurityPage view="操作审计" state={props.health}/></Frame>;if(['操作审计','数据修改','资金操作','权限变更','安全告警'].includes(view))return <Frame view={view}><AuditSecurityPage view={view} state={props.health}/></Frame>;return <ContentPage {...props} view={view}/>}
function ContentPage({view,work,units,members,member,tenant,busy,post}:{view:string;work:any;units:any[];members:any[];member:any;tenant:string;busy:boolean;post:any}){
 if(view==='我的待办'||view==='团队队列'||view==='SLA 与提醒'||view==='风险摘要')return <WorkQueuePage view={view} work={work} member={member}/>;
 if(view==='客服工单'||view==='投诉与争议')return <Frame view={view}><ServiceTickets busy={busy} canEdit={member?.role!=='audit'}/></Frame>;
 if(view==='通知模板')return <Frame view={view}><NotificationTemplates busy={busy}/></Frame>;
 if(view==='Telegram 业务渠道')return <Frame view={view}><BusinessBots state={work?.state} tenant={tenant} busy={busy} post={post}/></Frame>;
 if(view==='通知发送记录')return <Frame view={view}><TelegramNotifications admin canManage={member?.role==='admin'}/></Frame>;
 if(view==='应急事件')return <Frame view={view}><EmergencyAccess units={units} memberId={member?.id}/></Frame>;
 if(view==='审计导出')return <Frame view={view}><AuditIntegrity role={member?.role||''}/></Frame>;
 if(['客户漏斗','KYC 与审批','放款与还款','逾期与催收报表','资金监管报表','客服与投诉','自定义报表'].includes(view))return <Frame view={view}><ReportCenter customers={work?.customers||[]} loans={work?.state?.loans||[]} entries={work?.state?.entries||[]} notifications={work?.state?.notifications||[]} role={member?.role||''}/></Frame>;
     if(view==='KYC 审核队列')return <Frame view={view} title="KYC 审核订单"><KycOrders orders={work?.kycOrders||[]} scope={work?.scope||[]} units={units} members={members} role={member?.role||'audit'} renderAssignment={()=>null}/></Frame>;
 if(view==='贷款申请'||view==='审批协同')return <LoanWorkflowPanel view={view} work={work} member={member} busy={busy} post={post}/>;
 if(view==='放款管理')return <Frame view={view}><FundingPanel scope={work?.scope||[]} units={units} loans={work?.state?.loans||[]} events={work?.state?.events||[]} entries={work?.state?.entries||[]} role={member?.role||''} busy={busy} post={post}/></Frame>;
 if(view==='账单与还款')return <Frame view={view}><RepaymentPanel loans={work?.state?.loans||[]} events={work?.state?.events||[]} scope={work?.scope||[]} units={units} role={member?.role||''} busy={busy} post={post}/></Frame>;
 if(view==='提现与钱包'||view==='合同与签约'||view==='业务时间线')return <LoanPage view={view} work={work}/>;
     if(['资金监管','资金限额','冻结与解除','资金流水','对账异常','风控事件'].includes(view))return <RiskPage view={view} work={work} units={units} role={member?.role||''} memberId={member?.id}/>;
 if(view==='还款管理')return <Frame view={view}><RepaymentPanel loans={work?.state?.loans||[]} events={work?.state?.events||[]} scope={work?.scope||[]} units={units} role={member?.role||'admin'} busy={busy} post={post}/></Frame>;
 if(view==='贷后任务'||view==='逾期与催收')return <Frame view={view}><PostloanPanel/></Frame>;
     if(view==='客户列表')return <Frame view={view}><CustomerCenter customers={work?.customers||[]} events={work?.state?.events||[]}/></Frame>;
 if(view==='客户标签与分组')return <Frame view={view}><CustomerTags customers={work?.customers||[]}/></Frame>;
 if(view==='费率与费用')return <Frame view={view}><PricingIndependent pricing={work?.pricing} busy={busy} post={post}/></Frame>;
 return <ConfigPage view={view} work={work} units={units} members={members} member={member} busy={busy} post={post}/>;
}
